     for (let j = numZBits - 1; j >= 0; j--) {
       const bit = (z >> j) & 1

       uint8 = (uint8 << 1) + bit
       numUint8Bits++

       if (numUint8Bits === BITS_PER_BYTE) {
         uint8Array[numUint8s] = uint8
         numUint8s++
         uint8 = 0
         numUint8Bits = 0
       }
